#!/usr/bin/env python3
"""Embed shaders/*.frag into src/Shaders.hpp as a string map.

Source of truth stays the .frag files (editable, highlightable);
the generated header is build output, never committed.
"""
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent
OUT = ROOT / "src" / "Shaders.hpp"

entries = []
for frag in sorted((ROOT / "shaders").glob("*.frag")) + sorted((ROOT / "shaders").glob("*.vert")):
    src = frag.read_text()
    entries.append(f'    {{"{frag.name}", R"GLSL(\n{src})GLSL"}}')

OUT.write_text(
    "// GENERATED by embed.py — do not edit, edit shaders/*.frag instead.\n"
    "#pragma once\n\n"
    "#include <string>\n"
    "#include <unordered_map>\n\n"
    "inline const std::unordered_map<std::string, const char*> SHADERS = {\n"
    + ",\n".join(entries)
    + ",\n};\n"
)
print(f"wrote {OUT} ({len(entries)} shaders)")
